const initial = {
  tasks:[
    {title:'Revisar vetores e strings',meta:'C · 45 min',done:true},
    {title:'Resolver 2 problemas de lógica',meta:'beecrowd · 50 min',done:false},
    {title:'Criar rota GET da API de hábitos',meta:'FastAPI · 35 min',done:false}
  ],
  tracks:[
    {icon:'01',title:'Fundamentos de C',desc:'Lógica, memória e estrutura para pensar como programador.',value:58,color:'#61e8d5'},
    {icon:'02',title:'Python & algoritmos',desc:'Sintaxe expressiva, resolução de problemas e estruturas.',value:42,color:'#a79bff'},
    {icon:'03',title:'Git & colaboração',desc:'Versione com segurança e conte a história do seu código.',value:25,color:'#ffbd6e'},
    {icon:'04',title:'Backend & dados',desc:'APIs, banco de dados e serviços que resolvem problemas.',value:18,color:'#ff9db9'}
  ],
  exercises:[
    {name:'1001 — Extremamente Básico',tech:'beecrowd',status:'Concluído',note:'Entendi entrada e saída padrão.',kind:'complete'},
    {name:'Maior e posição',tech:'Python',status:'Em tentativa',note:'Revisar índice vs. posição humana.',kind:'attempt'},
    {name:'1114 — Senha Fixa',tech:'C',status:'Concluído',note:'Laço while e condição de parada.',kind:'complete'},
    {name:'URI 1068 — Balanço de parênteses',tech:'C',status:'Travado',note:'Problema de lógica: pilha e casos aninhados.',kind:'blocked'}
  ],
  projects:[
    {type:'PESSOAL · BACKEND',title:'API de hábitos',desc:'API REST para registrar hábitos, metas e sequência de dias.',tech:['FastAPI','PostgreSQL','JWT'],status:'em construção',link:'#'},
    {type:'ACADÊMICO · DADOS',title:'Análise de notas',desc:'Exploração de dados de desempenho com visualizações simples.',tech:['Python','Pandas','Jupyter'],status:'próximo passo: README',link:'#'},
    {type:'IDEIA · FULL STACK',title:'Controle de estudos',desc:'Uma versão menor deste painel, feita como projeto de portfólio.',tech:['Flask','SQLite','HTML/CSS'],status:'a planejar',link:'#'}
  ],
  reviews:['Vetores em C','Complexidade O(n)','git add, commit e push'],
  actions:[{text:'Atualizar currículo com a API de hábitos',done:false},{text:'Resolver 3 exercícios de arrays',done:false},{text:'Ler uma vaga e anotar requisitos recorrentes',done:true}],
  minutes:270
};
let state=JSON.parse(localStorage.getItem('rotaDevData')||'null')||initial;
state.calendar=state.calendar||[{day:1,title:'C · vetores'},{day:2,title:'Python · listas'},{day:4,title:'API de hábitos'}];
state.notes=state.notes||'';
state.weekGoal=state.weekGoal||'';
state.weekSessions=state.weekSessions||0;
state.career=state.career||[{text:'Currículo com projetos e links',done:false},{text:'GitHub organizado com README',done:false},{text:'LinkedIn atualizado',done:false},{text:'Portfólio revisado',done:false}];
state.githubUrl=state.githubUrl||'';
let currentFilter='todos';
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
function save(){localStorage.setItem('rotaDevData',JSON.stringify(state));}
function renderTasks(){const root=$('#tasks');root.innerHTML='';state.tasks.forEach((t,i)=>{const n=$('#taskTemplate').content.cloneNode(true);const input=n.querySelector('input');input.checked=t.done;input.addEventListener('change',()=>{state.tasks[i].done=input.checked;save();renderTasks()});n.querySelector('.task-title').textContent=t.title;n.querySelector('small').textContent=t.meta;root.append(n)});const done=state.tasks.filter(t=>t.done).length;$('#taskStatus').textContent=`${done} de ${state.tasks.length} concluídas`;$('#taskBar').style.width=`${state.tasks.length?done/state.tasks.length*100:0}%`}
function renderTracks(){const r=$('#tracks');r.innerHTML=state.tracks.map(t=>`<article class="card track" style="--track:${t.color}"><span class="track-icon">${t.icon}</span><h3>${t.title}</h3><p>${t.desc}</p><div class="progress-label"><span>PROGRESSO</span><span>${t.value}%</span></div><div class="progress"><i style="width:${t.value}%"></i></div></article>`).join('')}
function statusClass(k){return k==='complete'?'complete':k==='blocked'?'blocked':'attempt'}
function renderExercises(){const x=state.exercises.filter(e=>currentFilter==='todos'||e.tech===currentFilter);$('#exerciseRows').innerHTML=x.map(e=>`<tr><td>${e.name}</td><td><span class="pill">${e.tech}</span></td><td><span class="status ${statusClass(e.kind)}">${e.status}</span></td><td>${e.note}</td><td><button class="row-action" title="Editar">⋮</button></td></tr>`).join(''); const count=state.exercises.filter(e=>e.kind==='complete').length+10;$('#doneCount').innerHTML=`${count} <span>/ 28</span>`;$('#exerciseBar').style.width=`${Math.min(100,count/28*100)}%`}
function renderReviews(){const r=$('#reviews');r.innerHTML=state.reviews.map((v,i)=>`<div class="review-item"><span>↻</span>${v}<button data-review="${i}">feito</button></div>`).join('');$('#reviewCount').textContent=state.reviews.length;$$('[data-review]').forEach(b=>b.onclick=()=>{state.reviews.splice(+b.dataset.review,1);save();renderReviews()})}
function renderProjects(){const p=$('#projects');p.innerHTML=state.projects.map(x=>`<article class="card project"><span class="project-type">${x.type}</span><h3>${x.title}</h3><p>${x.desc}</p><div class="techs">${x.tech.map(t=>`<span>${t}</span>`).join('')}</div><div class="project-bottom"><span class="pill">${x.status}</span><a href="${x.link}" target="_blank">Repositório ↗</a></div></article>`).join('')}
function renderActions(){const r=$('#weeklyActions');r.innerHTML=state.actions.map((a,i)=>`<label class="weekly-action"><input type="checkbox" ${a.done?'checked':''} data-action="${i}"><span>${a.text}</span></label>`).join('');$$('[data-action]').forEach(x=>x.onchange=()=>{state.actions[+x.dataset.action].done=x.checked;save();renderActions()})}
function render(){renderTasks();renderTracks();renderExercises();renderReviews();renderProjects();renderActions();$('#weekTime').textContent=`${Math.floor(state.minutes/60)}h ${state.minutes%60}m`}
function modal(title,copy,fields,onSave){$('#modalContent').innerHTML=`<h2 class="modal-title">${title}</h2><p class="modal-copy">${copy}</p><div class="form-grid">${fields}</div><div class="modal-actions"><button class="btn ghost small" value="cancel">Cancelar</button><button class="btn primary small" value="default" id="modalSave">Salvar</button></div>`;$('#modal').showModal();$('#modalSave').onclick=e=>{e.preventDefault();onSave();$('#modal').close()}}
$('#openSession').onclick=()=>modal('Registrar estudo','Uma nota curta já basta para manter o histórico vivo.',`<label>Tempo em minutos<input id="mTime" type="number" min="1" value="45"></label><label>Em que você trabalhou?<input id="mTopic" placeholder="Ex.: laços em C"></label>`,()=>{state.minutes+=+$('#mTime').value||0;if($('#mTopic').value)state.tasks.push({title:`Revisar: ${$('#mTopic').value}`,meta:'registrado agora',done:true});save();render()});
$('#addTask').onclick=()=>modal('Adicionar tarefa','Mantenha tarefas pequenas e observáveis.',`<label>Tarefa<input id="mTitle" required placeholder="Ex.: resolver exercício"></label><label>Contexto / tempo<input id="mMeta" placeholder="Python · 30 min"></label>`,()=>{let t=$('#mTitle').value.trim();if(t){state.tasks.push({title:t,meta:$('#mMeta').value||'sem estimativa',done:false});save();renderTasks()}});
$('#addTrack').onclick=()=>modal('Nova trilha','Crie uma trilha para um tema que entrou no seu plano.',`<label>Nome<input id="mTitle" placeholder="Ex.: SQL"></label><label>Descrição<input id="mDesc" placeholder="O que você quer construir aqui?"></label>`,()=>{let t=$('#mTitle').value.trim();if(t){state.tracks.push({icon:String(state.tracks.length+1).padStart(2,'0'),title:t,desc:$('#mDesc').value||'Trilha personalizada para sua evolução.',value:0,color:'#8bb8ff'});save();renderTracks()}});
$('#addExercise').onclick=()=>modal('Cadastrar exercício','Registre também tentativas incompletas: elas são material de revisão.',`<label>Exercício<input id="mName" placeholder="Ex.: beecrowd 1002"></label><label>Tecnologia<select id="mTech"><option>C</option><option>Python</option><option>beecrowd</option></select></label><label>Status<select id="mStatus"><option value="attempt">Em tentativa</option><option value="complete">Concluído</option><option value="blocked">Travado</option></select></label><label>Tipo de dificuldade<select id="mIssue"><option>Problema de lógica</option><option>Erro de compilação</option><option>Entrada e saída</option><option>Clareza do código</option><option>Nenhuma — consegui concluir</option></select></label><label>O que aconteceu / próxima tentativa<textarea id="mNote" placeholder="Ex.: esqueci de atualizar o índice quando encontro um valor maior."></textarea></label>`,()=>{let n=$('#mName').value.trim(),k=$('#mStatus').value;if(n){const context=$('#mIssue').value;state.exercises.unshift({name:n,tech:$('#mTech').value,status:k==='complete'?'Concluído':k==='blocked'?'Travado':'Em tentativa',note:`${context}: ${$('#mNote').value||'sem observação ainda.'}`,kind:k});save();renderExercises();renderSignals()}});
$('#addProject').onclick=()=>modal('Novo projeto','Um bom próximo passo é concreto e pequeno.',`<label>Nome do projeto<input id="mTitle" placeholder="Ex.: API de biblioteca"></label><label>Próximo passo<textarea id="mDesc" placeholder="Ex.: criar modelo de usuário"></textarea></label><label>Tecnologias (separe por vírgula)<input id="mTech" placeholder="FastAPI, SQLite"></label><label>Link do repositório<input id="mLink" placeholder="https://github.com/... "></label>`,()=>{let t=$('#mTitle').value.trim();if(t){state.projects.unshift({type:'PESSOAL · EM EVOLUÇÃO',title:t,desc:$('#mDesc').value||'Defina o próximo passo deste projeto.',tech:$('#mTech').value.split(',').map(x=>x.trim()).filter(Boolean),status:'em construção',link:$('#mLink').value||'#'});save();renderProjects()}});
$('#addWeeklyAction').onclick=()=>modal('Ação da semana','Prefira uma ação que deixe evidência: commit, exercício, README ou currículo.',`<label>Ação<input id="mTitle" placeholder="Ex.: publicar README do projeto"></label>`,()=>{let t=$('#mTitle').value.trim();if(t){state.actions.push({text:t,done:false});save();renderActions()}});
$$('.filter').forEach(b=>b.onclick=()=>{$$('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentFilter=b.dataset.filter;renderExercises()});
$$('.hint-btn').forEach(b=>b.onclick=()=>{let p=b.nextElementSibling;p.classList.remove('hidden');b.classList.add('hidden');if(p.nextElementSibling)p.nextElementSibling.classList.remove('hidden')});
$('#codeInput').value=localStorage.getItem('rotaDevCode')||'';$('#codeInput').oninput=e=>localStorage.setItem('rotaDevCode',e.target.value);
$('#analyzeCode').onclick=()=>{const code=$('#codeInput').value.trim(),box=$('#feedback');if(!code){box.innerHTML='<strong>Comece com uma tentativa.</strong> Mesmo um rascunho nos permite discutir a lógica, sem entregar o caminho pronto.';box.classList.remove('hidden');return}let notes=[];if(!/for|while/.test(code))notes.push('Para este desafio, parece faltar uma repetição para percorrer os 5 valores.');if(!/max|maior/.test(code.toLowerCase()))notes.push('Pense em uma variável que guarde o maior valor encontrado até agora.');if(!/enumerate|range|for/.test(code)&&$('#langSelect').value==='Python')notes.push('Considere como você vai acompanhar a posição enquanto lê cada valor.');if(code.length<45)notes.push('Sua tentativa está bem curta; escreva primeiro o esqueleto da leitura e da comparação.');if(!notes.length)notes.push('A estrutura parece ter os elementos certos. Agora teste mentalmente empates e o primeiro valor.');box.innerHTML=`<strong>Feedback de raciocínio (sem solução completa)</strong><br>${notes.map(x=>'• '+x).join('<br>')}<br><span style="color:#9eafc4">Dica de clareza: use nomes que expressem intenção e teste com valores repetidos.</span>`;box.classList.remove('hidden')};
$$('[data-scroll]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.scroll).scrollIntoView({behavior:'smooth'}));
$('#resetData').onclick=()=>{if(confirm('Restaurar os dados de exemplo? Seus registros locais serão substituídos.')){localStorage.removeItem('rotaDevData');state=JSON.parse(JSON.stringify(initial));render()}};
let timerSeconds=25*60, timerHandle=null, activeWeek=0;
function fmtTimer(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function renderCalendar(){const days=['SEG 17','TER 18','QUA 19','QUI 20','SEX 21','SÁB 22','DOM 23'];$('#calendar').innerHTML=days.map((d,i)=>`<div class="calendar-day ${i===1?'today':''}"><b>${d}</b>${state.calendar.filter(e=>e.day===i).map(e=>`<span class="cal-event">${e.title}</span>`).join('')}</div>`).join('')}
function renderCareer(){const root=$('#careerChecklist');root.innerHTML=state.career.map((c,i)=>`<label class="career-check"><input type="checkbox" data-career="${i}" ${c.done?'checked':''}><span>${c.text}</span></label>`).join('');$$('[data-career]').forEach(x=>x.onchange=()=>{state.career[+x.dataset.career].done=x.checked;save();renderCareer()})}
function renderSignals(){const issue=state.exercises.filter(e=>e.kind!=='complete');const items=issue.length?issue.slice(0,3):[{name:'Nenhuma dificuldade urgente',note:'Continue registrando seus testes.'}];$('#difficultySignals').innerHTML=items.map(e=>`<div class="difficulty-item"><i>!</i><span>${e.name}</span></div>`).join('')}
function renderGithub(){const url=state.githubUrl;$('#githubUrl').value=url;const link=$('#githubLink');if(url){link.href=url;link.classList.remove('hidden')}else link.classList.add('hidden')}
function renderExtras(){renderCalendar();renderCareer();renderSignals();renderGithub();$('#studyNote').value=state.notes;$('#weekGoal').value=state.weekGoal;const target=(state.weekGoal.match(/\d+/)||['4'])[0];$('#weekGoalStatus').textContent=`${state.weekSessions} / ${target} sessões`;$('#weekGoalBar').style.width=`${Math.min(100,state.weekSessions/target*100)}%`;$('#timerDisplay').textContent=fmtTimer(timerSeconds)}
const originalRender=render;render=function(){originalRender();renderExtras()};
$('#addCalendar').onclick=()=>modal('Bloco na agenda','Escolha um estudo pequeno o bastante para caber no seu dia.',`<label>Estudo<input id="mTitle" placeholder="Ex.: revisar funções"></label><label>Dia<select id="mDay"><option value="0">Segunda</option><option value="1">Terça</option><option value="2">Quarta</option><option value="3">Quinta</option><option value="4">Sexta</option><option value="5">Sábado</option><option value="6">Domingo</option></select></label>`,()=>{let title=$('#mTitle').value.trim();if(title){state.calendar.push({title,day:+$('#mDay').value});save();renderCalendar()}});
$('#prevWeek').onclick=()=>{activeWeek--;$('.calendar-head strong').textContent='Semana anterior · plano livre'};$('#nextWeek').onclick=()=>{activeWeek++;$('.calendar-head strong').textContent='Semana seguinte · plano livre'};
$('#startTimer').onclick=()=>{const b=$('#startTimer');if(timerHandle){clearInterval(timerHandle);timerHandle=null;b.textContent='Continuar';$('#timerStatus').textContent='Sessão pausada. Retome quando estiver pronto.';return}b.textContent='Pausar';$('#timerStatus').textContent='Foco em andamento. Um passo de cada vez.';timerHandle=setInterval(()=>{timerSeconds--;$('#timerDisplay').textContent=fmtTimer(timerSeconds);if(timerSeconds<=0){clearInterval(timerHandle);timerHandle=null;timerSeconds=0;b.textContent='Começar';$('#timerStatus').textContent='Sessão concluída! Registre o que avançou.';state.minutes+=25;state.weekSessions++;save();renderExtras()}},1000)};
$('#resetTimer').onclick=()=>{clearInterval(timerHandle);timerHandle=null;timerSeconds=25*60;$('#startTimer').textContent='Começar';$('#timerStatus').textContent='Pronto para uma sessão de concentração.';renderExtras()};
$$('[data-minutes]').forEach(b=>b.onclick=()=>{clearInterval(timerHandle);timerHandle=null;timerSeconds=+b.dataset.minutes*60;$('#startTimer').textContent='Começar';renderExtras()});
$('#weekGoal').onchange=e=>{state.weekGoal=e.target.value;save();renderExtras()};$('#addSession').onclick=()=>{state.weekSessions++;save();renderExtras()};
$('#saveNote').onclick=()=>{state.notes=$('#studyNote').value;save();$('#saveNote').textContent='Salvo ✓';setTimeout(()=>$('#saveNote').textContent='Salvar anotação',1200)};
$('#saveGithub').onclick=()=>{let url=$('#githubUrl').value.trim();if(url&&!/^https:\/\/github\.com\//.test(url)){alert('Use um link que comece com https://github.com/');return}state.githubUrl=url;save();renderGithub()};
function download(name,type,body){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
$('#exportCsv').onclick=()=>{const rows=[['Exercício','Tecnologia','Status','Aprendizado / dificuldade'],...state.exercises.map(e=>[e.name,e.tech,e.status,e.note])];download('rota-dev-exercicios.csv','text/csv;charset=utf-8','\ufeff'+rows.map(r=>r.map(x=>`"${String(x).replaceAll('"','""')}"`).join(';')).join('\n'))};
$('#backupData').onclick=()=>download('rota-dev-backup.json','application/json',JSON.stringify(state,null,2));$('#printReport').onclick=()=>window.print();
$('#restoreData').onchange=e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{state=JSON.parse(reader.result);save();render();alert('Backup restaurado com sucesso.')}catch{alert('Não foi possível ler este backup.')}};reader.readAsText(file)};
render();
